1	package tools
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	
8		"github.com/modelcontextprotocol/go-sdk/mcp"
9		"github.com/nsega/mcp-todoist/internal/models"
10		"github.com/nsega/mcp-todoist/internal/todoist"
11	)
12	
13	// --- Input / Output types ---
14	
15	type CreateTaskInput struct {
16		Content     string   `json:"content" jsonschema:"The content/title of the task"`
17		Description string   `json:"description,omitempty" jsonschema:"Detailed description of the task (optional)"`
18		DueString   string   `json:"due_string,omitempty" jsonschema:"Natural language due date like 'tomorrow', 'next Monday', 'Jan 23' (optional)"`
19		Priority    int      `json:"priority,omitempty" jsonschema:"Task priority from 1 (normal) to 4 (urgent) (optional)"`
20		ProjectID   string   `json:"project_id,omitempty" jsonschema:"Project ID to create the task in (optional)"`
21		SectionID   string   `json:"section_id,omitempty" jsonschema:"Section ID to create the task in (optional)"`
22		ParentID    string   `json:"parent_id,omitempty" jsonschema:"Parent task ID for sub-tasks (optional)"`
23		Labels      []string `json:"labels,omitempty" jsonschema:"Labels to apply to the task (optional)"`
24		AssigneeID  string   `json:"assignee_id,omitempty" jsonschema:"User ID to assign the task to (optional)"`
25	}
26	
27	type CreateTaskOutput struct {
28		Success bool   `json:"success"`
29		Message string `json:"message"`
30	}
31	
32	type GetTasksInput struct {
33		ProjectID string `json:"project_id,omitempty" jsonschema:"Filter tasks by project ID (optional)"`
34		Filter    string `json:"filter,omitempty" jsonschema:"Natural language filter like 'today', 'tomorrow', 'next week', 'priority 1', 'overdue' (optional)"`
35		Priority  int    `json:"priority,omitempty" jsonschema:"Filter by priority level (1-4) (optional)"`
36		Limit     int    `json:"limit,omitempty" jsonschema:"Maximum number of tasks to return (optional, default 10)"`
37	}
38	
39	type GetTasksOutput struct {
40		Success bool   `json:"success"`
41		Message string `json:"message"`
42	}
43	
44	type UpdateTaskInput struct {
45		TaskID       string   `json:"task_id,omitempty" jsonschema:"Task ID to update (preferred over task_name)"`
46		TaskName     string   `json:"task_name,omitempty" jsonschema:"Name/content of the task to search for and update"`
47		Content      string   `json:"content,omitempty" jsonschema:"New content/title for the task (optional)"`
48		Description  string   `json:"description,omitempty" jsonschema:"New description for the task (optional)"`
49		DueString    string   `json:"due_string,omitempty" jsonschema:"New due date in natural language (optional)"`
50		Priority     int      `json:"priority,omitempty" jsonschema:"New priority level from 1 (normal) to 4 (urgent) (optional)"`
51		Labels       []string `json:"labels,omitempty" jsonschema:"New labels for the task (optional)"`
52		AssigneeID   string   `json:"assignee_id,omitempty" jsonschema:"User ID to assign the task to (optional)"`
53		DeadlineDate string   `json:"deadline_date,omitempty" jsonschema:"New deadline date in YYYY-MM-DD format (optional)"`
54	}
55	
56	type UpdateTaskOutput struct {
57		Success bool   `json:"success"`
58		Message string `json:"message"`
59	}
60	
61	type DeleteTaskInput struct {
62		TaskID   string `json:"task_id,omitempty" jsonschema:"Task ID to delete (preferred over task_name)"`
63		TaskName string `json:"task_name,omitempty" jsonschema:"Name/content of the task to search for and delete"`
64	}
65	
66	type DeleteTaskOutput struct {
67		Success bool   `json:"success"`
68		Message string `json:"message"`
69	}
70	
71	type CompleteTaskInput struct {
72		TaskID   string `json:"task_id,omitempty" jsonschema:"Task ID to complete (preferred over task_name)"`
73		TaskName string `json:"task_name,omitempty" jsonschema:"Name/content of the task to search for and complete"`
74	}
75	
76	type CompleteTaskOutput struct {
77		Success bool   `json:"success"`
78		Message string `json:"message"`
79	}
80	
81	type ReopenTaskInput struct {
82		TaskID   string `json:"task_id,omitempty" jsonschema:"Task ID to reopen (preferred over task_name)"`
83		TaskName string `json:"task_name,omitempty" jsonschema:"Name/content of the task to search for and reopen"`
84	}
85	
86	type ReopenTaskOutput struct {
87		Success bool   `json:"success"`
88		Message string `json:"message"`
89	}
90	
91	// --- helpers ---
92	
93	func resolveTaskID(c *todoist.Client, id, name string) (string, string, error) {
94		if id != "" {
95			return id, "", nil
96		}
97		if name == "" {
98			return "", "", fmt.Errorf("either task_id or task_name is required")
99		}
100		task, err := c.FindTaskByName(name)
101		if err != nil {
102			return "", "", err
103		}
104		if task == nil {
105			return "", "", nil // not found
106		}
107		return task.ID, task.Content, nil
108	}
109	
110	func textResult(msg string, isError bool) *mcp.CallToolResult {
111		return &mcp.CallToolResult{
112			Content: []mcp.Content{&mcp.TextContent{Text: msg}},
113			IsError: isError,
114		}
115	}
116	
117	// --- registrations ---
118	
119	func registerTaskTools(s *mcp.Server, c *todoist.Client) {
120		mcp.AddTool(s, &mcp.Tool{
121			Name:        "todoist_create_task",
122			Description: "Create a new task in Todoist with optional description, due date, priority, project, section, labels, and assignee",
123		}, func(ctx context.Context, req *mcp.CallToolRequest, input CreateTaskInput) (*mcp.CallToolResult, CreateTaskOutput, error) {
124			body := map[string]any{"content": input.Content}
125			if input.Description != "" {
126				body["description"] = input.Description
127			}
128			if input.DueString != "" {
129				body["due_string"] = input.DueString
130			}
131			if input.Priority > 0 && input.Priority <= 4 {
132				body["priority"] = input.Priority
133			}
134			if input.ProjectID != "" {
135				body["project_id"] = input.ProjectID
136			}
137			if input.SectionID != "" {
138				body["section_id"] = input.SectionID
139			}
140			if input.ParentID != "" {
141				body["parent_id"] = input.ParentID
142			}
143			if len(input.Labels) > 0 {
144				body["labels"] = input.Labels
145			}
146			if input.AssigneeID != "" {
147				body["assignee_id"] = input.AssigneeID
148			}
149	
150			task, err := c.CreateTask(body)
151			if err != nil {
152				return nil, CreateTaskOutput{Success: false, Message: err.Error()}, err
153			}
154	
155			msg := fmt.Sprintf("Task created:\nTitle: %s", task.Content)
156			if task.Description != "" {
157				msg += fmt.Sprintf("\nDescription: %s", task.Description)
158			}
159			if task.Due != nil && task.Due.String != "" {
160				msg += fmt.Sprintf("\nDue: %s", task.Due.String)
161			}
162			if task.Priority > 0 {
163				msg += fmt.Sprintf("\nPriority: %d", task.Priority)
164			}
165	
166			return textResult(msg, false), CreateTaskOutput{Success: true, Message: msg}, nil
167		})
168	
169		mcp.AddTool(s, &mcp.Tool{
170			Name:        "todoist_get_tasks",
171			Description: "Get a list of tasks from Todoist with various filters",
172		}, func(ctx context.Context, req *mcp.CallToolRequest, input GetTasksInput) (*mcp.CallToolResult, GetTasksOutput, error) {
173			var tasks []models.Task
174			var err error
175			if input.Filter != "" {
176				tasks, err = c.GetTasksByFilter(input.Filter)
177			} else {
178				tasks, err = c.GetTasks(input.ProjectID)
179			}
180			if err != nil {
181				return nil, GetTasksOutput{}, err
182			}
183	
184			// Apply priority filter.
185			if input.Priority > 0 && input.Priority <= 4 {
186				filtered := tasks[:0]
187				for _, t := range tasks {
188					if t.Priority == input.Priority {
189						filtered = append(filtered, t)
190					}
191				}
192				tasks = filtered
193			}
194	
195			// Apply limit.
196			limit := input.Limit
197			if limit == 0 {
198				limit = 10
199			}
200			if len(tasks) > limit {
201				tasks = tasks[:limit]
202			}
203	
204			var msg string
205			if len(tasks) == 0 {
206				msg = "No tasks found matching the criteria"
207			} else {
208				var lines []string
209				for _, t := range tasks {
210					s := fmt.Sprintf("- %s (ID: %s)", t.Content, t.ID)
211					if t.Description != "" {
212						s += fmt.Sprintf("\n  Description: %s", t.Description)
213					}
214					if t.Due != nil && t.Due.String != "" {
215						s += fmt.Sprintf("\n  Due: %s", t.Due.String)
216					}
217					if t.Priority > 0 {
218						s += fmt.Sprintf("\n  Priority: %d", t.Priority)
219					}
220					lines = append(lines, s)
221				}
222				msg = strings.Join(lines, "\n\n")
223			}
224	
225			return textResult(msg, false), GetTasksOutput{Success: true, Message: msg}, nil
226		})
227	
228		mcp.AddTool(s, &mcp.Tool{
229			Name:        "todoist_update_task",
230			Description: "Update an existing task in Todoist by task_id or by searching by name",
231		}, func(ctx context.Context, req *mcp.CallToolRequest, input UpdateTaskInput) (*mcp.CallToolResult, UpdateTaskOutput, error) {
232			id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
233			if err != nil {
234				return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
235			}
236			if id == "" {
237				msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
238				return textResult(msg, true), UpdateTaskOutput{Success: false, Message: msg}, nil
239			}
240	
241			body := map[string]any{}
242			if input.Content != "" {
243				body["content"] = input.Content
244			}
245			if input.Description != "" {
246				body["description"] = input.Description
247			}
248			if input.DueString != "" {
249				body["due_string"] = input.DueString
250			}
251			if input.Priority > 0 && input.Priority <= 4 {
252				body["priority"] = input.Priority
253			}
254			if len(input.Labels) > 0 {
255				body["labels"] = input.Labels
256			}
257			if input.AssigneeID != "" {
258				body["assignee_id"] = input.AssigneeID
259			}
260			if input.DeadlineDate != "" {
261				body["deadline_date"] = input.DeadlineDate
262			}
263	
264			updated, err := c.UpdateTask(id, body)
265			if err != nil {
266				return nil, UpdateTaskOutput{Success: false, Message: err.Error()}, err
267			}
268	
269			label := originalName
270			if label == "" {
271				label = id
272			}
273			msg := fmt.Sprintf("Task \"%s\" updated:\nNew Title: %s", label, updated.Content)
274			if updated.Description != "" {
275				msg += fmt.Sprintf("\nNew Description: %s", updated.Description)
276			}
277			if updated.Due != nil && updated.Due.String != "" {
278				msg += fmt.Sprintf("\nNew Due Date: %s", updated.Due.String)
279			}
280			if updated.Priority > 0 {
281				msg += fmt.Sprintf("\nNew Priority: %d", updated.Priority)
282			}
283	
284			return textResult(msg, false), UpdateTaskOutput{Success: true, Message: msg}, nil
285		})
286	
287		mcp.AddTool(s, &mcp.Tool{
288			Name:        "todoist_delete_task",
289			Description: "Delete a task from Todoist by task_id or by searching by name",
290		}, func(ctx context.Context, req *mcp.CallToolRequest, input DeleteTaskInput) (*mcp.CallToolResult, DeleteTaskOutput, error) {
291			id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
292			if err != nil {
293				return nil, DeleteTaskOutput{Success: false, Message: err.Error()}, err
294			}
295			if id == "" {
296				msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
297				return textResult(msg, true), DeleteTaskOutput{Success: false, Message: msg}, nil
298			}
299	
300			if err := c.DeleteTask(id); err != nil {
301				return nil, DeleteTaskOutput{Success: false, Message: err.Error()}, err
302			}
303	
304			label := originalName
305			if label == "" {
306				label = id
307			}
308			msg := fmt.Sprintf("Successfully deleted task: \"%s\"", label)
309			return textResult(msg, false), DeleteTaskOutput{Success: true, Message: msg}, nil
310		})
311	
312		mcp.AddTool(s, &mcp.Tool{
313			Name:        "todoist_complete_task",
314			Description: "Mark a task as complete by task_id or by searching by name",
315		}, func(ctx context.Context, req *mcp.CallToolRequest, input CompleteTaskInput) (*mcp.CallToolResult, CompleteTaskOutput, error) {
316			id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
317			if err != nil {
318				return nil, CompleteTaskOutput{Success: false, Message: err.Error()}, err
319			}
320			if id == "" {
321				msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
322				return textResult(msg, true), CompleteTaskOutput{Success: false, Message: msg}, nil
323			}
324	
325			if err := c.CloseTask(id); err != nil {
326				return nil, CompleteTaskOutput{Success: false, Message: err.Error()}, err
327			}
328	
329			label := originalName
330			if label == "" {
331				label = id
332			}
333			msg := fmt.Sprintf("Successfully completed task: \"%s\"", label)
334			return textResult(msg, false), CompleteTaskOutput{Success: true, Message: msg}, nil
335		})
336	
337		mcp.AddTool(s, &mcp.Tool{
338			Name:        "todoist_reopen_task",
339			Description: "Reopen a completed task by task_id or by searching by name",
340		}, func(ctx context.Context, req *mcp.CallToolRequest, input ReopenTaskInput) (*mcp.CallToolResult, ReopenTaskOutput, error) {
341			id, originalName, err := resolveTaskID(c, input.TaskID, input.TaskName)
342			if err != nil {
343				return nil, ReopenTaskOutput{Success: false, Message: err.Error()}, err
344			}
345			if id == "" {
346				msg := fmt.Sprintf("Could not find a task matching \"%s\"", input.TaskName)
347				return textResult(msg, true), ReopenTaskOutput{Success: false, Message: msg}, nil
348			}
349	
350			if err := c.ReopenTask(id); err != nil {
351				return nil, ReopenTaskOutput{Success: false, Message: err.Error()}, err
352			}
353	
354			label := originalName
355			if label == "" {
356				label = id
357			}
358			msg := fmt.Sprintf("Successfully reopened task: \"%s\"", label)
359			return textResult(msg, false), ReopenTaskOutput{Success: true, Message: msg}, nil
360		})
361	}
