15	// router dispatches to handlers based on method+path prefix.
16	type router struct {
17		mu       sync.Mutex
18		handlers []routeEntry
19	}
20	
21	type routeEntry struct {
22		method  string
23		prefix  string
24		handler http.HandlerFunc
25	}
26	
27	func newRouter() *router {
28		return &router{}
